import { IPromoDetails } from './models/promo-details';
import { ITimeKeeperLimit } from './models/time-keeper-limit';
import { IResultCodeData } from './models/result-code-data';
import { IGameServerResponse } from './response/response';

export interface IServerEvents<TResponse extends IGameServerResponse> {
    ON_SUCCESSFUL_RESULT: (response: TResponse) => void,
    ON_TIMEKEEPER_RESULT: (tkDetails: ITimeKeeperLimit) => void,
    ON_REALITYCHECK_RESULT: (limit: number) => void,
    /** Unauthorised events may want to redirect to login or just show an error */
    ON_NOTAUTHORISED_ERROR: (response: TResponse) => void,
    ON_PROMO_RESULT: (promoDetails: IPromoDetails[]) => void,
    ON_BONUSINPLAY_ERROR: () => void,
    ON_LOWBALANCE_ERROR: () => void,
    ON_NOSESSION_ERROR: (response: TResponse) => void,
    ON_NETWORK_ERROR: () => void,
    ON_ERROR_TO_NOTIFY: (result: IResultCodeData) => void,
    ON_GAME_UNAVAILABLE: (response: TResponse) => void,
    ON_COOLOFF_WINDOW_HIT: () => void,
    ON_TIME_LIMIT_REACHED_WINDOW_HIT: () => void,
    ON_INVALID_STAKE: () => void,
    ON_GAME_IN_GAME_FREEZE: () => void,
    ON_BINGO_SELF_EXCLUSION: (data: any) => void,
    ON_ARCADE_SELF_EXCLUSION: (data: any) => void
}